export function detalleDe(num: number): AsignaturaDetalle | undefined {
  return MIR_DETALLE[num];
}

export function pesoColor(pct: number): string {
  if (pct >= 12) return '#E5484D';
  if (pct >= 8) return '#F5A623';
  if (pct >= 4) return '#E8C547';
  return '#4Fae6b';
}
